import { describe, it, expect } from 'bun:test';
import { slugify, titleize, camelize } from '../src/utils';

describe('slugify', () => {
  it('lowercases and dashes', () => {
    expect(slugify('Hello World')).toBe('hello-world');
  });
  it('strips punctuation', () => {
    expect(slugify('a b!')).toBe('a-b');
  });
});

describe('titleize', () => {
  it('capitalizes words', () => {
    expect(titleize('hello world')).toBe('Hello World');
  });
  it('keeps acronyms', () => {
    expect(titleize('HTTP server')).toBe('HTTP Server');
  });
});

describe('camelize', () => {
  it('camel-cases dashed keys', () => {
    expect(camelize('user-id')).toBe('userId');
  });
});

